"A propósito... senhor."

en:
//【景明】
<voice name='景明' class='景明' src='voice/ma04/0050780a00'>
//「何か」
"Yes?"

pt:
//【景明】
<voice name='景明' class='景明' src='voice/ma04/0050780a00'>
