pt:
//【一条】
<voice name='一条' class='一条' src='voice/ma04/0050790a02'>
//「あの大尉と婆さんはどうしたんです？」
"O que houve com o capitão e a velhinha?"

en:
//【一条】
<voice name='一条' class='一条' src='voice/ma04/0050800a02'>
//「あ……すいません。やっぱりいいです。
//　そりゃ、色々ありますよね……あんなんで
//も軍人だったんだし」
"Uh... Sorry. Never mind! They're GHQ. Probably busy."

pt:
//【一条】
<voice name='一条' class='一条' src='voice/ma04/0050800a02'>
//「あ……すいません。やっぱりいいです。
//　そりゃ、色々ありますよね……あんなんで
//も軍人だったんだし」
"Ah... Desculpe. Deixa pra lá! Eles são da GHQ. Devem estar ocupados."

en:
//【一条】
<voice name='一条' class='一条' src='voice/ma04/0050810a02'>
//「じゃ、行ってきます」
"I'll see you later!"

pt:
//【一条】
<voice name='一条' class='一条' src='voice/ma04/0050810a02'>
